    complexityGuide: {"work":"How many nodes are visited?","workChoices":[["once","Each node once"],["nested","Each node per level"]],"workCorrect":"once","workWhy":"A single level-order sweep touches each node once.","memory":"What grows with the tree?","memoryChoices":[["width","The widest level of nodes"],["constant","A fixed amount"]],"memoryCorrect":"width","memoryWhy":"The frontier can hold up to a full level of nodes.","final":[["n-n","Time O(n), space O(n)"],["n-constant","Time O(n), space O(1)"],["h-h","Time O(h), space O(h)"]],"finalCorrect":"n-n"},
