    complexityGuide: {"work":"How many cells are output?","workChoices":[["grid","Every cell once"],["nested","Each cell per ring"]],"workCorrect":"grid","workWhy":"Each of the m·n cells is pushed exactly once.","memory":"What storage grows with the matrix?","memoryChoices":[["output","The output list of all cells"],["constant","Only the four bounds"]],"memoryCorrect":"output","memoryWhy":"The result holds all m·n values.","final":[["mn-mn","Time O(m · n), space O(m · n)"],["mn-constant","Time O(m · n), space O(1)"],["quadratic-mn","Time O((m · n)²), space O(m · n)"]],"finalCorrect":"mn-mn"},
