    complexityGuide: {"work":"How much work processes the graph?","workChoices":[["ve","Each course and edge once"],["quadratic","Each course against every other"]],"workCorrect":"ve","workWhy":"Every node is dequeued once and every edge relaxed once.","memory":"What storage grows with the graph?","memoryChoices":[["graph","Adjacency list + indegree + queue"],["constant","A fixed amount"]],"memoryCorrect":"graph","memoryWhy":"Storage scales with courses and prerequisite edges.","final":[["ve-ve","Time O(V + E), space O(V + E)"],["v2-v","Time O(V²), space O(V)"],["ve-constant","Time O(V + E), space O(1)"]],"finalCorrect":"ve-ve"},
