  'Cheapest Flights Within K Stops': lesson('Cheapest Flights Within K Stops', {
    brief: "Find the cheapest price from src to dst using at most k stops, or -1.",
    concepts: ["Bounded Bellman-Ford","Relax on last round’s prices"],
    intuition: "Allowing at most k stops means paths of at most k+1 edges. Run k+1 relaxation rounds, but each round relaxes using the PREVIOUS round’s prices (a snapshot), so a single round never chains multiple new edges — that is what caps the number of stops.",
    inputOutput: ["n cities; flights [from,to,price]; src, dst, k stops allowed.","Return the cheapest cost within k stops, or -1.","Input: n=4, flights=[[0,1,100],[1,2,100],[2,0,100],[1,3,600],[2,3,200]], src=0, dst=3, k=1\nOutput: 700"],
    conceptChoices: ["Bellman-Ford, k+1 rounds relaxing on a snapshot","Plain Dijkstra ignoring the stop limit","DFS every path and take the minimum"],
    algorithm: ["Set all prices to infinity except the source at 0.","Repeat k + 1 times (paths of at most k + 1 edges).","Snapshot the current prices so this round relaxes only on last round’s values.","For each flight, relax the destination if going through its source is cheaper.","After the rounds, return the destination price, or -1 if still infinite."],
    fixes: ["Relax against a SNAPSHOT of last round’s prices, so one round adds at most one edge (bounding stops).","Run exactly k + 1 rounds — k stops means up to k + 1 flights."],
    complexity: "Time O(k · E); space O(n).",
    exercises: [{"prompt":"Which line bounds each round to one extra stop?","correct":"const temp = prices.slice();","choices":["const temp = prices.slice();","const temp = prices;","const temp = new Array(n).fill(Infinity);"],"why":"Relaxing into a copy of last round’s prices prevents chaining several new edges within a single round.","wrong":{"const temp = prices;":"Aliasing lets a round use edges it just added, exceeding the stop limit.","const temp = new Array(n).fill(Infinity);":"Discarding prior prices loses all progress between rounds."}},{"prompt":"Which line relaxes a flight using the previous round’s prices?","correct":"if (prices[from] + price < temp[to]) temp[to] = prices[from] + price;","choices":["if (prices[from] + price < temp[to]) temp[to] = prices[from] + price;","if (temp[from] + price < temp[to]) temp[to] = temp[from] + price;","if (prices[from] + price < prices[to]) prices[to] = prices[from] + price;"],"why":"Reading prices[from] (last round) and writing temp[to] (this round) keeps each round to one added edge.","wrong":{"if (temp[from] + price < temp[to]) temp[to] = temp[from] + price;":"Reading temp[from] lets this round chain edges, breaking the stop bound.","if (prices[from] + price < prices[to]) prices[to] = prices[from] + price;":"Writing back into prices mutates the snapshot mid-round."}}],
    complexityGuide: {"work":"How much relaxation work?","workChoices":[["ke","(k + 1) rounds over all flights"],["ve","One pass over the graph"]],"workCorrect":"ke","workWhy":"Each of the k + 1 rounds relaxes every flight.","memory":"What storage grows with the cities?","memoryChoices":[["prices","A price per city (and a snapshot)"],["const","A fixed amount"]],"memoryCorrect":"prices","memoryWhy":"Two price arrays of length n are used.","final":[["ke-n","Time O(k · E), space O(n)"],["elogv-v","Time O(E log V), space O(V)"],["ve-constant","Time O(V + E), space O(1)"]],"finalCorrect":"ke-n"},
  }),
