    inputOutput: ["nums: distinct values, ascending then rotated; target.","Return the index of target, or -1.","Input: nums = [4,5,6,7,0,1,2], target = 0\nOutput: 4"],
    conceptChoices: ["Binary search, discarding the half that can’t hold the target","Scan linearly for the target","Find the pivot, then two binary searches"],
    algorithm: ["Binary search with inclusive left/right bounds.","If mid is the target, return it.","Determine which side of mid is sorted (left sorted when nums[left] <= nums[mid]).","If the target lies within the sorted side’s range, search there; otherwise search the other side.","Return -1 if the bounds cross without a match."],
    fixes: ["Decide the sorted half with nums[left] <= nums[mid].","Only move into a half when the target is provably within its sorted range."],
    complexity: "Time O(log n); space O(1).",
